import{_ as e,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const s=JSON.parse('{"title":"高级 RAG","description":"根据基础 RAG 的具体失败类型，选择高级索引、查询变换、纠错、图关系或 Agentic RAG。","frontmatter":{"title":"高级 RAG","description":"根据基础 RAG 的具体失败类型，选择高级索引、查询变换、纠错、图关系或 Agentic RAG。"},"headers":[],"relativePath":"py-agent/knowledge/advanced-rag/index.md","filePath":"py-agent/knowledge/advanced-rag/index.md","lastUpdated":1785318762000}'),r={name:"py-agent/knowledge/advanced-rag/index.md"};function l(d,a,o,c,g,p){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="高级-rag" tabindex="-1">高级 RAG <a class="header-anchor" href="#高级-rag" aria-label="Permalink to &quot;高级 RAG&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>高级 RAG 不是技术名词集合，而是针对基础链路已被评测确认的失败采取不同控制策略。本分组按介入位置展开：索引阶段、查询阶段、检索验证阶段、关系建模阶段和动态决策阶段。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成后，你应该能够：</p><ol><li>根据检索粒度和跨文档关系选择高级索引；</li><li>区分查询改写、多查询、分解和假设文档方法；</li><li>为低相关或证据不足设计自适应与纠错分支；</li><li>判断实体关系和全局主题问题是否值得使用 GraphRAG；</li><li>判断是否需要让 Agent 动态选择知识源和检索次数；</li><li>用基础 RAG 作为对照评估质量、延迟和成本。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/knowledge/advanced-rag/advanced-indexing">高级索引策略</a></li><li><a href="/py-agent/knowledge/advanced-rag/query-rewriting-decomposition">查询改写与问题分解</a></li><li><a href="/py-agent/knowledge/advanced-rag/adaptive-corrective-rag">自适应与纠错 RAG</a></li><li><a href="/py-agent/knowledge/advanced-rag/graphrag">GraphRAG</a></li><li><a href="/py-agent/knowledge/advanced-rag/agentic-rag">Agentic RAG</a></li></ol><h2 id="_3-选择原则" tabindex="-1">3. 选择原则 <a class="header-anchor" href="#_3-选择原则" aria-label="Permalink to &quot;3. 选择原则&quot;">​</a></h2><p>先定位失败发生在哪一层，再只增加对应策略。没有离线基线、轨迹和成本数据时，不应因为名称“高级”就替换稳定的 2-Step RAG。</p><h2 id="_4-分组边界" tabindex="-1">4. 分组边界 <a class="header-anchor" href="#_4-分组边界" aria-label="Permalink to &quot;4. 分组边界&quot;">​</a></h2><p>本组讲架构和决策机制，不展开完整图数据库运维、多 Agent 协作或框架内部实现。</p>',12)])])}const _=e(r,[["render",l]]);export{s as __pageData,_ as default};
